using Aurora386.Core.IO;

namespace Aurora386.Core.Devices.IsaPnp;

/// <summary>
/// The ISA Plug and Play protocol (specification 1.0a), as seen from the
/// three ports it lives on: ADDRESS at 279h, WRITE_DATA at A79h, and a
/// READ_DATA port the software chooses between 203h and 3FFh.
///
/// ISA has no way to ask a slot what is in it, so Plug and Play invents
/// one on top of three ports. Every card starts deaf. A 32-byte key,
/// generated by a shift register so that nothing else would ever write
/// it by accident, wakes them all. Then isolation: each card shifts out a
/// 72-bit serial number one bit at a time, and whenever a card with a 0
/// sees another card driving a 1 it drops out, so after 72 bits exactly one
/// card is left and can be given a number. Repeat until nobody answers,
/// and the software has found every card and can read what each one wants
/// and tell it where to go.
///
/// The bus emulates all the cards at once, which is what makes the
/// isolation trivial: it can see every card's bit and decide who drops
/// out, where real cards have to infer it from what the wire does.
/// </summary>
public sealed partial class IsaPnpBus : IIoDevice
{
    public const ushort AddressPort = 0x279;
    public const ushort WriteDataPort = 0xA79;
    public const ushort DefaultReadDataPort = 0x203;

    private static readonly byte[] InitiationKey = BuildKey();

    private readonly List<IsaPnpCard> _cards = new();
    private IoBus? _io;
    private ushort _readDataPort = DefaultReadDataPort;
    private int _keyPosition;
    private byte _address;
    private int _isolationPhase;
    private int _isolationBit;
    private bool _isolationAnyOne;
    private bool _snapshotPortMappingDetached;

    public IReadOnlyList<IsaPnpCard> Cards => _cards;
    public ushort ReadDataPort => _readDataPort;

    /// <summary>Cards that have been given a select number: what the PnP BIOS reports as found.</summary>
    public int AssignedCount => _cards.Count(c => c.Csn != 0);

    public void Add(IsaPnpCard card) => _cards.Add(card);

    public void Register(IoBus io)
    {
        _io = io;
        io.Register(AddressPort, this);
        io.Register(WriteDataPort, this);
        io.Register(_readDataPort, this);
    }

    private static byte[] BuildKey()
    {
        // The linear feedback shift register of the specification, started
        // at 6Ah: each step shifts right and feeds bits 0 and 1 back in at
        // the top. 32 steps give the sequence that begins 6A B5 DA ED.
        byte[] key = new byte[32];
        byte lfsr = 0x6A;
        for (int i = 0; i < 32; i++)
        {
            key[i] = lfsr;
            lfsr = (byte)((lfsr >> 1) | (((lfsr ^ (lfsr >> 1)) & 1) << 7));
        }
        return key;
    }

    // --- writes ------------------------------------------------------------------

    public void WriteByte(ushort port, byte value)
    {
        if (port == AddressPort)
        {
            WriteAddress(value);
        }
        else if (port == WriteDataPort)
        {
            WriteData(value);
        }
    }

    private void WriteAddress(byte value)
    {
        _address = value;

        // Cards waiting for the key watch the address port for it. Two
        // zeros reset the shift register; a wrong byte does too.
        if (value == InitiationKey[_keyPosition])
        {
            if (++_keyPosition == InitiationKey.Length)
            {
                _keyPosition = 0;
                foreach (IsaPnpCard card in _cards)
                    if (card.State == IsaPnpCard.CardState.WaitForKey)
                    {
                        card.State = IsaPnpCard.CardState.Sleep;
                    }
            }
        }
        else
        {
            _keyPosition = 0;
        }
    }

    private void WriteData(byte value)
    {
        switch (_address)
        {
            case 0x00:
                // Set RD_DATA port: the value is bits 9:2 of the address, and
                // the low two bits are always set -- 203h, 207h, 20Bh...
                MoveReadDataPort((ushort)((value << 2) | 3));
                return;

            case 0x02:
                // Config control. Bit 0 resets every card's configuration,
                // bit 1 sends every card back to waiting for the key, bit 2
                // clears every select number so isolation can start again.
                foreach (IsaPnpCard card in _cards)
                {
                    if ((value & 0x01) != 0)
                    {
                        foreach (IsaPnpLogicalDevice device in card.LogicalDevices)
                        {
                            device.Reset();
                            device.NotifyConfigured();
                        }
                    }
                    if ((value & 0x01) != 0 || (value & 0x02) != 0)
                    {
                        card.State = IsaPnpCard.CardState.WaitForKey;
                    }
                    if ((value & 0x04) != 0)
                    {
                        card.Csn = 0;
                    }
                }
                return;

            case 0x03:
                // Wake[CSN]. The card with that number goes to Config -- or,
                // for zero, every card without a number goes to Isolation --
                // and everybody else goes to sleep. Either way the pointers
                // into the identifier and the resource data start over.
                foreach (IsaPnpCard card in _cards)
                {
                    if (card.State == IsaPnpCard.CardState.WaitForKey)
                    {
                        continue;
                    }
                    if (card.Csn == value)
                    {
                        card.State = value == 0 ? IsaPnpCard.CardState.Isolation : IsaPnpCard.CardState.Config;
                        card.SerialBit = 0;
                        card.ResourcePointer = 0;
                    }
                    else
                    {
                        card.State = IsaPnpCard.CardState.Sleep;
                    }
                }
                _isolationBit = 0;
                _isolationPhase = 0;
                return;

            case 0x06:
                // Card select number: given to the one card left in
                // isolation, which then moves on to being configured.
                foreach (IsaPnpCard card in _cards)
                {
                    if (card.State != IsaPnpCard.CardState.Isolation)
                    {
                        continue;
                    }
                    card.Csn = value;
                    card.State = IsaPnpCard.CardState.Config;
                }
                return;

            case 0x07:
            {
                IsaPnpCard? card = Configuring();
                if (card is not null && value < card.LogicalDevices.Count)
                {
                    card.CurrentDevice = value;
                }
                return;
            }

            case >= 0x30 and <= 0x7F:
            {
                IsaPnpCard? card = Configuring();
                if (card is null)
                {
                    return;
                }
                IsaPnpLogicalDevice device = card.LogicalDevices[card.CurrentDevice];
                bool wasActive = device.Active;
                device.Registers[_address] = _address == 0x30 ? (byte)(value & 1) : value;

                // The chip moves when it is switched on or off, and when its
                // address changes while it is on. Writing registers to a
                // sleeping device is just bookkeeping until it is activated.
                if (_address == 0x30 ? wasActive != device.Active : device.Active)
                    device.NotifyConfigured();
                return;
            }
        }
    }

    private void MoveReadDataPort(ushort port)
    {
        if (port == _readDataPort)
        {
            if (_snapshotPortMappingDetached)
            {
                RebuildSnapshotPortMapping();
            }

            return;
        }
        _io?.Unregister(_readDataPort, 1, this);
        _readDataPort = port;
        _io?.Register(_readDataPort, this);
        _snapshotPortMappingDetached = false;
    }

    /// <summary>The card in the Config state, if any: the one that answers reads and takes register writes.</summary>
    private IsaPnpCard? Configuring() => _cards.FirstOrDefault(c => c.State == IsaPnpCard.CardState.Config);

    // --- reads -------------------------------------------------------------------

    public byte ReadByte(ushort port)
    {
        if (port != _readDataPort)
        {
            return 0xFF;
        }

        switch (_address)
        {
            case 0x01:
                return ReadIsolation();

            case 0x04:
                return Configuring()?.NextResourceByte() ?? 0xFF;

            case 0x05:
                // Status: bit 0 says a resource byte is ready, which here it
                // always is -- there is no EEPROM to wait for.
                return Configuring() is not null ? (byte)0x01 : (byte)0xFF;

            case 0x06:
                return Configuring()?.Csn ?? 0xFF;

            case 0x07:
                return (byte?)Configuring()?.CurrentDevice ?? 0xFF;

            case >= 0x30 and <= 0x7F:
            {
                IsaPnpCard? card = Configuring();
                return card is null ? (byte)0xFF : card.LogicalDevices[card.CurrentDevice].Registers[_address];
            }

            default:
                return 0xFF;
        }
    }

    /// <summary>
    /// One read of the Serial Isolation register. The software reads twice
    /// per bit: a card whose bit is 1 drives 55h and then AAh; a card whose
    /// bit is 0 drives nothing and listens, and if it hears the 55h/AAh
    /// pair from somebody else it withdraws. After 72 bits one card is left.
    /// </summary>
    private byte ReadIsolation()
    {
        var isolating = _cards.Where(c => c.State == IsaPnpCard.CardState.Isolation).ToList();
        if (isolating.Count == 0 || _isolationBit >= 72)
        {
            return 0xFF;
        }

        if (_isolationPhase == 0)
        {
            _isolationAnyOne = isolating.Any(c => c.SerialBitAt(_isolationBit) == 1);
            _isolationPhase = 1;
            return _isolationAnyOne ? (byte)0x55 : (byte)0xFF;
        }

        _isolationPhase = 0;
        if (_isolationAnyOne)
        {
            foreach (IsaPnpCard card in isolating)
                if (card.SerialBitAt(_isolationBit) == 0)
                {
                    card.State = IsaPnpCard.CardState.Sleep;
                }
        }
        _isolationBit++;
        return _isolationAnyOne ? (byte)0xAA : (byte)0xFF;
    }
}
